 function persist(s){Fin.validate(s);const json=JSON.stringify(s);if(native){if(!LocalDevice.save(json))throw Error('保存失败，数据未修改');}else localStorage.setItem('squirrelfin.v1',json);state=s;storageError=false;render();}
 function invalidate(s,t){for(const a of s.assets.filter(a=>a.id===t.asset||a.id===t.to))a.snapshots.filter(v=>v.date>=t.date).forEach(v=>v.confirmed=false);}
 function change(fn){const s=JSON.parse(JSON.stringify(state));const before=new Set(s.transactions.map(t=>t.id));fn(s);s.transactions.filter(t=>!before.has(t.id)).forEach(t=>invalidate(s,t));persist(s);}
 function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').classList.remove('light-entry','month-picker','asset-entry');$('modal').classList.toggle('has-form',html.includes('id="entry-form"'));if(!$('modal').open)$('modal').showModal();$('modal-body').scrollTop=0;}
 const close=()=>$('modal').close();
