 function txDetail(id){const t=state.transactions.find(t=>t.id===id),a=state.assets.find(a=>a.id===t.asset),locked=t.linked||state.transactions.some(x=>x.linked===id)||state.executions.some(e=>e.transaction===id||e.sourceTransaction===id)||state.assets.some(a=>a.sold===id);modal('流水详情',`<div class="muted">${types[t.type]} · ${t.date} · ${esc(a?.name||'仅记收支')}</div><div class="detail-value">¥ ${money(t.amount)}</div><p>${esc(t.note||'无备注')}</p>${t.sourceCategory?`<p class="muted">原分类：${esc(t.sourceCategory)}</p>`:''}${t.type==='expense'&&!t.linked?`<p>${esc(t.category||'未分类')} · ${Fin.expenseNatures[t.nature]||'性质未分类'}</p>`:''}${t.to?`<p>转入：${esc(state.assets.find(a=>a.id===t.to).name)}</p>`:''}${locked?'<p class="disclosure">关联资金或出售记录需保持一致。</p>':btn('edit-tx','编辑记录','primary',`data-id="${esc(id)}"`)}<section class="inline-help"><h3>更多操作</h3>${btn('delete-tx','删除流水','text-button danger',`data-id="${esc(id)}"`)}</section>`);}
 function tips(){if(!state.assets.length)return '';const t=totals(),gross=t.cash+t.investment;const investments=state.assets.filter(a=>a.kind==='investment');const largest=investments.sort((a,b)=>Fin.balance(state,b,today())-Fin.balance(state,a,today()))[0];let advice='';if(gross>0)advice+=`<div class="callout">现金占已登记金融资产的 ${pct(t.cash/gross)}。结合近期支出检查应急资金是否足够；余额不等于所有资金都能立即取用。</div>`;if(largest&&gross>0)advice+=`<div class="callout">「${esc(largest.name)}」占已登记金融资产的 ${pct(Fin.balance(state,largest,today())/gross)}。定期检查单项资产集中度与自身风险承受能力。</div>`;if(t.debt>0)advice+=`<div class="callout">已登记负债 ¥ ${money(t.debt)}。核对到期时间与还款资金，避免只看资产余额。</div>`;if(!advice)advice='<div class="callout">按需登记资产、负债和估值，才能更准确地检查财富分布。</div>';return `<section class="card wealth-tips"><div class="section-head"><h2>财富小建议</h2><span class="muted">根据本地记录计算</span></div>${advice}<div class="disclosure">提醒依据仅来自已登记资产，不包含未记录的收入、支出或账户；风险标签由你填写。</div></section>`;}
 function alignReportTables(){document.querySelectorAll('.data-table-wrap').forEach(e=>e.classList.toggle('scrollable',e.clientWidth>0&&e.scrollWidth>e.clientWidth+1));}
 window.addEventListener('resize',()=>requestAnimationFrame(()=>{alignOverviewAmounts();alignReportTables();}));
 let lastDialAngle=null;
 function initMonthDial(){
  const dial=document.querySelector('.home-month-dial');if(!dial)return;dial.tabIndex=0;let start=null,accumulated=0,lock=0;
  dial.addEventListener('pointerdown',e=>{if(!e.target.closest('button'))start=e.clientX;});dial.addEventListener('pointerup',e=>{if(start!==null&&Math.abs(e.clientX-start)>25)stepOverviewMonth(e.clientX<start?1:-1,true);start=null;});dial.addEventListener('pointercancel',()=>start=null);
  dial.addEventListener('wheel',e=>{e.preventDefault();if(Date.now()<lock)return;accumulated+=e.deltaY||e.deltaX;if(Math.abs(accumulated)>32){const direction=accumulated>0?1:-1;accumulated=0;lock=Date.now()+200;stepOverviewMonth(direction,true);}},{passive:false});
  dial.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();stepOverviewMonth(e.key==='ArrowLeft'?-1:1,true);}});
  const needle=dial.querySelector('[data-dial-angle]'),angle=Number(needle.dataset.dialAngle)-90;needle.style.transform='rotate('+angle+'deg)';if(lastDialAngle!==null&&lastDialAngle!==angle&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)needle.animate([{transform:'rotate('+lastDialAngle+'deg)'},{transform:'rotate('+angle+'deg)'}],{duration:240,easing:'ease-out'});lastDialAngle=angle;
 }
 function render(){nav();$('page-title').textContent={overview:'我的总览',assets:'资产台账',ledger:'收支分析'}[page];$('header-date').textContent=today().replaceAll('-',' / ')+' · SQUIRRELFIN';$('privacy').textContent=hidden?'🙈':'👀';$('privacy').setAttribute('aria-label',hidden?'关闭防窥，显示金额':'开启防窥，隐藏金额');$('privacy').setAttribute('aria-pressed',String(hidden));$('privacy').title=hidden?'防窥已开启':'开启防窥';$('content').innerHTML=({overview,assets,ledger})[page]();alignOverviewAmounts();alignReportTables();initMonthDial();document.querySelectorAll('[data-progress]').forEach(e=>e.style.width=Math.min(100,Number(e.dataset.progress))+'%');document.querySelectorAll('[data-bar]').forEach(e=>e.style.height=e.dataset.bar+'%');document.querySelectorAll('[data-allocation]').forEach(e=>e.style.width=e.dataset.allocation+'%');}
 const options=as=>as.map(a=>`<option value="${esc(a.id)}">${esc(a?.name||'仅记收支')}</option>`).join('');
